/**
 * Per-mod facts the editor's own logic needs (creating a blank map, adding a player, level
 * caps) — the things that used to be constants lifted from one mod's tables. Generated by
 * the pipeline from Grace / GLord / GUnits of the mod.
 */
import { z } from "zod";
import { MOD_SCHEMA_VERSION } from "./manifest.js";
import { GlobalId } from "./ids.js";

/**
 * A race of the mod, as the "add race" operation needs it (port of toolsqt
 * D2MapEditor::addRace): the Grace row plus the units and lord a new player starts with.
 */
export const ModRace = z.object({
  /** Stable editor key: "empire" | "legions" | "clans" | "undead" | "elves" | "neutral" | … */
  key: z.string().min(1),
  /** Grace.RACE_ID. */
  raceId: GlobalId,
  /** Grace.RACE_TYPE (Lrace id). */
  raceType: z.number().int(),
  /** Display name (Grace.NAME_TXT resolved through Tglobal). */
  name: z.string(),
  /** A player can be created for this race (false for neutrals). */
  playable: z.boolean(),
  /** Grace.GUARDIAN and its base-level hit points. */
  guardian: GlobalId.optional(),
  guardianHp: z.number().int().optional(),
  /** Grace.LEADER_1 and its base-level hit points. */
  leader: GlobalId.optional(),
  leaderHp: z.number().int().optional(),
  /** The race's category-0 lord (GLord). */
  lord: GlobalId.optional(),
  /** Lterrain id stamped under a new capital of this race. */
  terrain: z.number().int().optional(),
});
export type ModRace = z.infer<typeof ModRace>;

export const ModProfile = z.object({
  schemaVersion: z.literal(MOD_SCHEMA_VERSION),
  races: z.array(ModRace).default([]),
  /** The item a new capital starts with (addRace's constant). */
  capitalItem: GlobalId.optional(),
  /** Number of GUnits rows — the unit level cap is 65536 / unitCount (reference editor rule). */
  unitCount: z.number().int().nonnegative().optional(),
});
export type ModProfile = z.infer<typeof ModProfile>;
